using System.Globalization;
using System.Text;

namespace PralayDrishti.Core.External;

/// <summary>
/// Writes a DualSPHysics (v5.x) case for the same near-field problem our internal WCSPH solves: a flume that
/// follows the river bed profile, the reservoir block behind the dam, optional structure. Bed geometry goes in
/// as an STL (numpy-stl in the Python world; here a small binary STL writer). Run on a CUDA box / Colab.
/// </summary>
public static class DualSphysicsExporter
{
    private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

    public sealed record Case(
        double[] ProfileX,       // m, prototype or model units - consistent with everything else
        double[] ProfileZ,
        double ReservoirLength,
        double WaterLevel,
        double Dp,
        double Width,
        double TimeMax,
        double[] GaugeX,
        double? StructureX = null,
        double StructureHeight = 0,
        double Density = 1000);

    public static string Write(Case c, string dir, string name = "DamBreak")
    {
        Directory.CreateDirectory(dir);
        WriteBedStl(Path.Combine(dir, "bed.stl"), c.ProfileX, c.ProfileZ, c.Width);

        double xmin = c.ProfileX[0], xmax = c.ProfileX[^1];
        double zmin = c.ProfileZ.Min() - 5 * c.Dp;
        double zmax = Math.Max(c.WaterLevel, c.ProfileZ.Max()) + (c.WaterLevel - c.ProfileZ.Min()) * 1.5;
        double damX = 0;
        double resStart = -c.ReservoirLength;

        var sb = new StringBuilder();
        sb.AppendLine("""<?xml version="1.0" encoding="UTF-8" ?>""");
        sb.AppendLine($"<!-- Generated by PralayDrishti {DateTime.UtcNow:yyyy-MM-dd HH:mm} UTC. Check parameter names against your DualSPHysics version. -->");
        sb.AppendLine("<case>");
        sb.AppendLine("  <casedef>");
        sb.AppendLine("    <constantsdef>");
        sb.AppendLine("      <gravity x=\"0\" y=\"0\" z=\"-9.81\" />");
        sb.AppendLine($"      <rhop0 value=\"{F(c.Density)}\" />");
        sb.AppendLine("      <hswl value=\"0\" auto=\"true\" />");
        sb.AppendLine("      <gamma value=\"7\" />");
        sb.AppendLine("      <speedsystem value=\"0\" auto=\"true\" />");
        sb.AppendLine("      <coefsound value=\"20\" />");
        sb.AppendLine("      <speedsound value=\"0\" auto=\"true\" />");
        sb.AppendLine("      <coefh value=\"1.2\" />");
        sb.AppendLine("      <cflnumber value=\"0.2\" />");
        sb.AppendLine("    </constantsdef>");
        sb.AppendLine("    <mkconfig boundcount=\"240\" fluidcount=\"9\" />");
        sb.AppendLine("    <geometry>");
        sb.AppendLine($"      <definition dp=\"{F(c.Dp)}\">");
        sb.AppendLine($"        <pointmin x=\"{F(xmin - 2 * c.Dp)}\" y=\"{F(-2 * c.Dp)}\" z=\"{F(zmin)}\" />");
        sb.AppendLine($"        <pointmax x=\"{F(xmax + 2 * c.Dp)}\" y=\"{F(c.Width + 2 * c.Dp)}\" z=\"{F(zmax)}\" />");
        sb.AppendLine("      </definition>");
        sb.AppendLine("      <commands>");
        sb.AppendLine("        <mainlist>");
        sb.AppendLine("          <setshapemode>actual | dp | bound</setshapemode>");
        sb.AppendLine("          <setdrawmode mode=\"full\" />");
        sb.AppendLine("          <!-- river bed -->");
        sb.AppendLine("          <setmkbound mk=\"0\" />");
        sb.AppendLine("          <drawfilestl file=\"bed.stl\" />");
        sb.AppendLine("          <!-- side walls of the flume and the upstream end wall -->");
        sb.AppendLine("          <setmkbound mk=\"1\" />");
        sb.AppendLine($"          <drawbox><boxfill>solid</boxfill><point x=\"{F(xmin)}\" y=\"{F(-c.Dp)}\" z=\"{F(zmin)}\" /><size x=\"{F(xmax - xmin)}\" y=\"{F(c.Dp)}\" z=\"{F(zmax - zmin)}\" /></drawbox>");
        sb.AppendLine($"          <drawbox><boxfill>solid</boxfill><point x=\"{F(xmin)}\" y=\"{F(c.Width)}\" z=\"{F(zmin)}\" /><size x=\"{F(xmax - xmin)}\" y=\"{F(c.Dp)}\" z=\"{F(zmax - zmin)}\" /></drawbox>");
        sb.AppendLine($"          <drawbox><boxfill>solid</boxfill><point x=\"{F(resStart - c.Dp)}\" y=\"0\" z=\"{F(zmin)}\" /><size x=\"{F(c.Dp)}\" y=\"{F(c.Width)}\" z=\"{F(zmax - zmin)}\" /></drawbox>");
        if (c.StructureX is double sx)
        {
            double zb = Interp(c.ProfileX, c.ProfileZ, sx);
            sb.AppendLine("          <!-- structure: force on mk=2 is what MeasureTool/ComputeForces reports -->");
            sb.AppendLine("          <setmkbound mk=\"2\" />");
            sb.AppendLine($"          <drawbox><boxfill>solid</boxfill><point x=\"{F(sx)}\" y=\"0\" z=\"{F(zb)}\" /><size x=\"{F(2 * c.Dp)}\" y=\"{F(c.Width)}\" z=\"{F(c.StructureHeight)}\" /></drawbox>");
        }
        sb.AppendLine("          <!-- reservoir water, gate removed at t = 0 -->");
        sb.AppendLine("          <setmkfluid mk=\"0\" />");
        sb.AppendLine($"          <fillbox x=\"{F(0.5 * (resStart + damX))}\" y=\"{F(c.Width / 2)}\" z=\"{F(c.WaterLevel - c.Dp)}\">");
        sb.AppendLine("            <modefill>void</modefill>");
        sb.AppendLine($"            <point x=\"{F(resStart)}\" y=\"0\" z=\"{F(zmin)}\" />");
        sb.AppendLine($"            <size x=\"{F(damX - resStart)}\" y=\"{F(c.Width)}\" z=\"{F(c.WaterLevel - zmin)}\" />");
        sb.AppendLine("          </fillbox>");
        sb.AppendLine("        </mainlist>");
        sb.AppendLine("      </commands>");
        sb.AppendLine("    </geometry>");
        sb.AppendLine("  </casedef>");
        sb.AppendLine("  <execution>");
        sb.AppendLine("    <parameters>");
        sb.AppendLine("      <parameter key=\"SavePosDouble\" value=\"0\" />");
        sb.AppendLine("      <parameter key=\"StepAlgorithm\" value=\"2\" comment=\"Symplectic\" />");
        sb.AppendLine("      <parameter key=\"VerletSteps\" value=\"40\" />");
        sb.AppendLine("      <parameter key=\"Kernel\" value=\"2\" comment=\"Wendland\" />");
        sb.AppendLine("      <parameter key=\"ViscoTreatment\" value=\"1\" comment=\"Artificial\" />");
        sb.AppendLine($"      <parameter key=\"Visco\" value=\"{(c.Density > 1200 ? "0.1" : "0.01")}\" />");
        sb.AppendLine("      <parameter key=\"ViscoBoundFactor\" value=\"1\" />");
        sb.AppendLine("      <parameter key=\"DensityDT\" value=\"2\" comment=\"Fourtakas\" />");
        sb.AppendLine("      <parameter key=\"DensityDTvalue\" value=\"0.1\" />");
        sb.AppendLine("      <parameter key=\"Shifting\" value=\"0\" />");
        sb.AppendLine("      <parameter key=\"RigidAlgorithm\" value=\"1\" />");
        sb.AppendLine("      <parameter key=\"DtIni\" value=\"0.0001\" />");
        sb.AppendLine("      <parameter key=\"DtMin\" value=\"0.00001\" />");
        sb.AppendLine($"      <parameter key=\"TimeMax\" value=\"{F(c.TimeMax)}\" />");
        sb.AppendLine($"      <parameter key=\"TimeOut\" value=\"{F(c.TimeMax / 100)}\" />");
        sb.AppendLine("      <parameter key=\"RhopOutMin\" value=\"700\" />");
        sb.AppendLine("      <parameter key=\"RhopOutMax\" value=\"1300\" />");
        sb.AppendLine("    </parameters>");
        sb.AppendLine("  </execution>");
        sb.AppendLine("</case>");
        File.WriteAllText(Path.Combine(dir, $"{name}_Def.xml"), sb.ToString());

        var pts = new StringBuilder("POINTS\n");
        foreach (var x in c.GaugeX) pts.AppendLine($"{F(x)} {F(c.Width / 2)} {F(Interp(c.ProfileX, c.ProfileZ, x) + c.Dp)}");
        File.WriteAllText(Path.Combine(dir, "gauges.txt"), pts.ToString());

        string run = $"""
@echo off
rem Adjust DSPH to your DualSPHysics bin folder
set DSPH=C:\DualSPHysics_v5.2\bin\windows
"%DSPH%\GenCase_win64.exe" {name}_Def out\{name} -save:all
"%DSPH%\DualSPHysics5.2_win64.exe" -gpu out\{name} out -dirdataout data -svres
"%DSPH%\MeasureTool_win64.exe" -dirin out\data -points gauges.txt -onlytype:-all,+fluid -height -savecsv out\Gauges
"%DSPH%\ComputeForces_win64.exe" -dirin out\data -onlymk:2 -savecsv out\Force
"%DSPH%\PartVTK_win64.exe" -dirin out\data -savevtk out\vtk\PartFluid -onlytype:-all,+fluid
""";
        File.WriteAllText(Path.Combine(dir, "run_windows.bat"), run);
        string sh = run.Replace("@echo off\r\n", "").Replace("@echo off\n", "").Replace("rem ", "# ")
            .Replace("set DSPH=C:\\DualSPHysics_v5.2\\bin\\windows", "DSPH=/opt/DualSPHysics/bin/linux")
            .Replace("\"%DSPH%\\", "\"$DSPH/").Replace("_win64.exe", "_linux64").Replace("\\", "/");
        File.WriteAllText(Path.Combine(dir, "run_linux.sh"), "#!/bin/sh\n" + sh);
        return Path.Combine(dir, $"{name}_Def.xml");
    }

    /// <summary>Closed solid: profile surface extruded across the flume width, down to a flat base.</summary>
    public static void WriteBedStl(string path, double[] xs, double[] zs, double width)
    {
        double zb = zs.Min() - 10;
        var tris = new List<(double[] a, double[] b, double[] c)>();
        void Quad(double[] p0, double[] p1, double[] p2, double[] p3) { tris.Add((p0, p1, p2)); tris.Add((p0, p2, p3)); }
        for (int i = 1; i < xs.Length; i++)
        {
            double x0 = xs[i - 1], x1 = xs[i], z0 = zs[i - 1], z1 = zs[i];
            Quad(new[] { x0, 0, z0 }, new[] { x1, 0, z1 }, new[] { x1, width, z1 }, new[] { x0, width, z0 });   // top
            Quad(new[] { x0, 0, zb }, new[] { x0, width, zb }, new[] { x1, width, zb }, new[] { x1, 0, zb });   // bottom
            Quad(new[] { x0, 0, zb }, new[] { x1, 0, zb }, new[] { x1, 0, z1 }, new[] { x0, 0, z0 });           // side y=0
            Quad(new[] { x0, width, zb }, new[] { x0, width, z0 }, new[] { x1, width, z1 }, new[] { x1, width, zb });
        }
        Quad(new[] { xs[0], 0, zb }, new[] { xs[0], 0, zs[0] }, new[] { xs[0], width, zs[0] }, new[] { xs[0], width, zb });
        Quad(new[] { xs[^1], 0, zb }, new[] { xs[^1], width, zb }, new[] { xs[^1], width, zs[^1] }, new[] { xs[^1], 0, zs[^1] });

        using var w = new BinaryWriter(File.Create(path));
        var header = new byte[80];
        Encoding.ASCII.GetBytes("PralayDrishti river bed").CopyTo(header, 0);
        w.Write(header);
        w.Write((uint)tris.Count);
        foreach (var (a, b, c) in tris)
        {
            var u = new[] { b[0] - a[0], b[1] - a[1], b[2] - a[2] };
            var v = new[] { c[0] - a[0], c[1] - a[1], c[2] - a[2] };
            var nx = u[1] * v[2] - u[2] * v[1];
            var ny = u[2] * v[0] - u[0] * v[2];
            var nz = u[0] * v[1] - u[1] * v[0];
            double len = Math.Sqrt(nx * nx + ny * ny + nz * nz);
            if (len < 1e-12) len = 1;
            foreach (var x in new[] { nx / len, ny / len, nz / len }) w.Write((float)x);
            foreach (var p in new[] { a, b, c }) foreach (var x in p) w.Write((float)x);
            w.Write((ushort)0);
        }
    }

    private static double Interp(double[] xs, double[] ys, double x)
    {
        if (x <= xs[0]) return ys[0];
        for (int i = 1; i < xs.Length; i++)
            if (x <= xs[i]) return ys[i - 1] + (x - xs[i - 1]) / (xs[i] - xs[i - 1]) * (ys[i] - ys[i - 1]);
        return ys[^1];
    }

    private static string F(double v) => v.ToString("0.######", Inv);
}
